import csv
series = {'e0dd5f44': 'F3_Z01_temp', 'b7f22e0c': 'F3_Z01_heat_set', '5b98cbc1': 'F3_Z01_cool_set', '6275dc72': 'VAV_F3_Z01_damper'}
rows=list(csv.reader(open(VALUES_CSV)))[1:]
from collections import defaultdict
d=defaultdict(list)
for rid,ts,val in rows:
    if rid in series:
        d[rid].append((ts,float(val)))
for k in d:
    d[k].sort()
    n=len(d[k])
    print(series[k], 'n=',n, 'first', d[k][0], 'last', d[k][-1])
    # monthly means from 2017-06 to 2019-01
    from collections import defaultdict
    mm=defaultdict(list)
    for ts,v in d[k]:
        mm[ts[:7]].append(v)
    for m in sorted(mm):
        if m < '2017-05' or m > '2019-01': continue
        print(' ', m, round(sum(mm[m])/len(mm[m]),2), len(mm[m]))
